 * A lagged default quote is a previous business day's value, so the date's own value is re-fetched from source 3.
 * Kept in a separate cache entry so the display board still gets the default quote.
 */
public BigDecimal settlementRate(String currency, LocalDate date) {
    FxQuote q = quote(currency, date);
    if (!q.lagged()) return q.rate();
    String pair = CurrencyPairs.pairOf(currency);
    return cache.computeIfAbsent(pair + "@" + date + "@src" + SETTLEMENT_SOURCE, k -> {
        vendorCalls++;
        return FxqClient.parse(client.rate(pair, date, SETTLEMENT_SOURCE));
    }).rate();
}

